import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

export function resolveDataFile(customPath) {
  if (customPath) {
    return path.resolve(customPath);
  }
  if (process.env.BOOKS_FILE) {
    return path.resolve(process.env.BOOKS_FILE);
  }
  return path.resolve(process.cwd(), 'books.json');
}

export class BookStore {
  constructor(filePath) {
    this.filePath = resolveDataFile(filePath);
  }

  _ensureFile() {
    const dir = path.dirname(this.filePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    if (!fs.existsSync(this.filePath)) {
      fs.writeFileSync(this.filePath, JSON.stringify([], null, 2), 'utf8');
    }
  }

  _readRaw() {
    this._ensureFile();
    try {
      const content = fs.readFileSync(this.filePath, 'utf8').trim();
      if (!content) return [];
      const parsed = JSON.parse(content);
      if (Array.isArray(parsed)) return parsed;
      if (parsed && Array.isArray(parsed.books)) return parsed.books;
      return [];
    } catch {
      return [];
    }
  }

  _writeRaw(books) {
    this._ensureFile();
    const tempFile = `${this.filePath}.${process.pid}.${Date.now()}.tmp`;
    fs.writeFileSync(tempFile, JSON.stringify(books, null, 2), 'utf8');
    fs.renameSync(tempFile, this.filePath);
  }

  getAll() {
    const books = this._readRaw();
    return books.map((b) => this._normalize(b));
  }

  getById(id) {
    const books = this.getAll();
    return books.find((b) => String(b.id) === String(id)) || null;
  }

  add({ title, author, notes = '', status = 'reading', finished }) {
    const cleanTitle = typeof title === 'string' ? title.trim() : '';
    const cleanAuthor = typeof author === 'string' ? author.trim() : '';
    const cleanNotes = typeof notes === 'string' ? notes.trim() : '';

    if (!cleanTitle) {
      const err = new Error('Title is required');
      err.status = 400;
      throw err;
    }
    if (!cleanAuthor) {
      const err = new Error('Author is required');
      err.status = 400;
      throw err;
    }

    const isFinished =
      finished === true ||
      status === 'finished' ||
      status === 'completed' ||
      status === 'read';

    const now = new Date().toISOString();
    const books = this.getAll();

    const slugBase = `${cleanTitle}-${cleanAuthor}`
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 40);
    const shortId = crypto.randomBytes(3).toString('hex');
    const id = slugBase ? `${slugBase}-${shortId}` : shortId;

    const newBook = {
      id,
      title: cleanTitle,
      author: cleanAuthor,
      notes: cleanNotes,
      status: isFinished ? 'finished' : 'reading',
      finished: isFinished,
      createdAt: now,
      finishedAt: isFinished ? now : null,
    };

    books.push(newBook);
    this._writeRaw(books);
    return newBook;
  }

  update(id, updates = {}) {
    const books = this.getAll();
    const index = books.findIndex((b) => String(b.id) === String(id));
    if (index === -1) {
      return null;
    }

    const current = books[index];
    const updated = { ...current };

    if (updates.title !== undefined) {
      const cleanTitle = String(updates.title).trim();
      if (!cleanTitle) {
        const err = new Error('Title cannot be empty');
        err.status = 400;
        throw err;
      }
      updated.title = cleanTitle;
    }

    if (updates.author !== undefined) {
      const cleanAuthor = String(updates.author).trim();
      if (!cleanAuthor) {
        const err = new Error('Author cannot be empty');
        err.status = 400;
        throw err;
      }
      updated.author = cleanAuthor;
    }

    if (updates.notes !== undefined) {
      updated.notes = String(updates.notes).trim();
    }

    if (updates.status !== undefined || updates.finished !== undefined) {
      const wantFinished =
        updates.finished === true ||
        updates.finished === 'true' ||
        updates.status === 'finished' ||
        updates.status === 'completed' ||
        updates.status === 'read';
      const wantReading =
        updates.finished === false ||
        updates.finished === 'false' ||
        updates.status === 'reading' ||
        updates.status === 'current';

      if (wantFinished) {
        updated.status = 'finished';
        updated.finished = true;
        updated.finishedAt = updated.finishedAt || new Date().toISOString();
      } else if (wantReading) {
        updated.status = 'reading';
        updated.finished = false;
        updated.finishedAt = null;
      }
    }

    books[index] = updated;
    this._writeRaw(books);
    return updated;
  }

  markFinished(id) {
    return this.update(id, { status: 'finished', finished: true });
  }

  delete(id) {
    const books = this.getAll();
    const index = books.findIndex((b) => String(b.id) === String(id));
    if (index === -1) return false;
    books.splice(index, 1);
    this._writeRaw(books);
    return true;
  }

  _normalize(book) {
    const isFinished =
      book.finished === true ||
      book.status === 'finished' ||
      book.status === 'completed' ||
      book.status === 'read';
    return {
      id: String(book.id),
      title: String(book.title || ''),
      author: String(book.author || ''),
      notes: String(book.notes || ''),
      status: isFinished ? 'finished' : 'reading',
      finished: isFinished,
      createdAt: book.createdAt || null,
      finishedAt: book.finishedAt || (isFinished ? book.createdAt || null : null),
    };
  }
}

