export function renderHomePage(books = []) {
  const readingBooks = books.filter((b) => !b.finished && b.status !== 'finished');
  const finishedBooks = books.filter((b) => b.finished || b.status === 'finished');

  const renderBookItem = (book, isReading) => {
    const id = escapeHtml(book.id);
    const title = escapeHtml(book.title);
    const author = escapeHtml(book.author);
    const notes = escapeHtml(book.notes);

    return `
      <li class="book-item" data-book-id="${id}" data-status="${isReading ? 'reading' : 'finished'}">
        <div class="book-info">
          <a href="/books/${encodeURIComponent(book.id)}" class="book-title-link">${title}</a>
          <div class="book-author">by <span class="author-name">${author}</span></div>
          ${notes ? `<div class="book-notes-preview">${notes}</div>` : ''}
        </div>
        <div class="book-actions">
          ${
            isReading
              ? `<form method="POST" action="/books/${encodeURIComponent(book.id)}/finish" class="finish-form" data-id="${id}" style="margin:0;">
                  <button type="submit" class="btn btn-primary btn-sm finish-btn" data-id="${id}">Mark as Finished</button>
                </form>`
              : `<span class="badge badge-finished">Finished</span>`
          }
          <a href="/books/${encodeURIComponent(book.id)}" class="btn btn-secondary btn-sm">View</a>
        </div>
      </li>
    `;
  };

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Reading Tracker</title>
  <style>${STYLES}</style>
</head>
<body>
  <div class="container">
    <header>
      <h1><a href="/">Reading Tracker</a></h1>
      <p>Keep track of the books you're reading</p>
    </header>

    <section class="card" aria-labelledby="add-book-heading">
      <h2 id="add-book-heading">Add a Book</h2>
      <form id="add-book-form" class="add-book-form" method="POST" action="/books">
        <div class="form-group">
          <label for="title">Title</label>
          <input type="text" id="title" name="title" placeholder="e.g. The Left Hand of Darkness" required />
        </div>
        <div class="form-group">
          <label for="author">Author</label>
          <input type="text" id="author" name="author" placeholder="e.g. Ursula K. Le Guin" required />
        </div>
        <div class="form-group full-width">
          <label for="notes">Notes</label>
          <textarea id="notes" name="notes" placeholder="Thoughts, favorite quotes, or chapter notes..."></textarea>
        </div>
        <div class="form-group full-width" style="flex-direction: row; justify-content: flex-end;">
          <button type="submit" class="btn btn-primary">Add Book</button>
        </div>
      </form>
    </section>

    <section id="currently-reading" class="section-block" aria-labelledby="reading-heading">
      <h2 id="reading-heading">
        Currently Reading
        <span class="count-pill" id="reading-count">${readingBooks.length}</span>
      </h2>
      ${
        readingBooks.length > 0
          ? `<ul class="book-list" id="reading-list">
              ${readingBooks.map((b) => renderBookItem(b, true)).join('')}
            </ul>`
          : `<p class="empty-state" id="reading-empty">No books currently being read. Add one above!</p>
             <ul class="book-list" id="reading-list" style="display:none;"></ul>`
      }
    </section>

    <section id="finished-books" class="section-block" aria-labelledby="finished-heading">
      <h2 id="finished-heading">
        Finished
        <span class="count-pill" id="finished-count">${finishedBooks.length}</span>
      </h2>
      ${
        finishedBooks.length > 0
          ? `<ul class="book-list" id="finished-list">
              ${finishedBooks.map((b) => renderBookItem(b, false)).join('')}
            </ul>`
          : `<p class="empty-state" id="finished-empty">No finished books yet.</p>
             <ul class="book-list" id="finished-list" style="display:none;"></ul>`
      }
    </section>
  </div>

  <script>
    (function() {
      const addForm = document.getElementById('add-book-form');
      if (addForm && window.fetch) {
        addForm.addEventListener('submit', async function(e) {
          e.preventDefault();
          const formData = new FormData(addForm);
          const payload = {
            title: formData.get('title'),
            author: formData.get('author'),
            notes: formData.get('notes') || ''
          };
          try {
            const res = await fetch('/api/books', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
              body: JSON.stringify(payload)
            });
            if (res.ok) {
              window.location.reload();
            } else {
              addForm.submit();
            }
          } catch {
            addForm.submit();
          }
        });
      }

      document.addEventListener('submit', async function(e) {
        const form = e.target.closest('.finish-form');
        if (!form || !window.fetch) return;
        e.preventDefault();
        const id = form.getAttribute('data-id');
        try {
          const res = await fetch('/api/books/' + encodeURIComponent(id) + '/finish', {
            method: 'POST',
            headers: { 'Accept': 'application/json' }
          });
          if (res.ok) {
            window.location.reload();
          } else {
            form.submit();
          }
        } catch {
          form.submit();
        }
      });
    })();
  </script>
</body>
</html>`;
}

export function renderBookPage(book, baseUrl = '') {
  const id = escapeHtml(book.id);
  const title = escapeHtml(book.title);
  const author = escapeHtml(book.author);
  const notes = escapeHtml(book.notes);
  const isFinished = Boolean(book.finished || book.status === 'finished');
  const canonicalPath = `/books/${encodeURIComponent(book.id)}`;
  const shareUrl = baseUrl ? `${baseUrl}${canonicalPath}` : canonicalPath;

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>${title} — Reading Tracker</title>
  <style>${STYLES}</style>
</head>
<body>
  <div class="container">
    <header>
      <h1><a href="/">Reading Tracker</a></h1>
      <p><a href="/" class="btn btn-secondary btn-sm">&larr; Back to all books</a></p>
    </header>

    <article class="card" data-book-id="${id}">
      <div style="display: flex; justify-content: space-between; align-items: flex-start; gap: 1rem; flex-wrap: wrap;">
        <div>
          <h2 id="book-title" style="font-size: 1.65rem; margin-bottom: 0.25rem;">${title}</h2>
          <div id="book-author" class="book-author" style="font-size: 1.1rem;">by <span class="author-name">${author}</span></div>
        </div>
        <div>
          ${
            isFinished
              ? `<span class="badge badge-finished" id="book-status">Finished</span>`
              : `<span class="badge badge-reading" id="book-status">Currently Reading</span>`
          }
        </div>
      </div>

      <div class="detail-meta">
        ${
          !isFinished
            ? `<form method="POST" action="/books/${encodeURIComponent(book.id)}/finish" id="detail-finish-form" style="margin:0;">
                <button type="submit" class="btn btn-primary btn-sm">Mark as Finished</button>
              </form>`
            : `<form method="POST" action="/books/${encodeURIComponent(book.id)}/reading" id="detail-reading-form" style="margin:0;">
                <button type="submit" class="btn btn-secondary btn-sm">Move to Currently Reading</button>
              </form>`
        }
      </div>

      <section aria-labelledby="notes-heading">
        <h3 id="notes-heading" style="font-size: 1.05rem; margin-bottom: 0.5rem;">My Notes</h3>
        <div id="book-notes" class="notes-box">${notes ? notes : '<span style="color: var(--muted); font-style: italic;">No notes added yet.</span>'}</div>

        <details style="margin-bottom: 1rem;">
          <summary style="cursor: pointer; font-weight: 600; font-size: 0.9rem; color: var(--accent);">Edit Notes / Details</summary>
          <form method="POST" action="/books/${encodeURIComponent(book.id)}" id="edit-notes-form" style="margin-top: 0.75rem; display: flex; flex-direction: column; gap: 0.75rem;">
            <div class="form-group">
              <label for="edit-title">Title</label>
              <input type="text" id="edit-title" name="title" value="${title}" required />
            </div>
            <div class="form-group">
              <label for="edit-author">Author</label>
              <input type="text" id="edit-author" name="author" value="${author}" required />
            </div>
            <div class="form-group">
              <label for="edit-notes">Notes</label>
              <textarea id="edit-notes" name="notes">${notes}</textarea>
            </div>
            <div>
              <button type="submit" class="btn btn-primary btn-sm">Save Changes</button>
            </div>
          </form>
        </details>
      </section>

      <div class="share-box">
        <label for="share-link" style="font-size: 0.85rem;">Share link to this book:</label>
        <input type="text" id="share-link" readonly value="${escapeHtml(shareUrl)}" onclick="this.select()" />
        <button type="button" id="copy-link-btn" class="btn btn-secondary btn-sm">Copy Link</button>
        <span id="copy-toast" class="toast">Copied!</span>
      </div>
    </article>
  </div>

  <script>
    (function() {
      const shareInput = document.getElementById('share-link');
      if (shareInput && window.location && window.location.href) {
        shareInput.value = window.location.origin + '${canonicalPath}';
      }
      const copyBtn = document.getElementById('copy-link-btn');
      const toast = document.getElementById('copy-toast');
      if (copyBtn && shareInput) {
        copyBtn.addEventListener('click', async function() {
          try {
            if (navigator.clipboard && navigator.clipboard.writeText) {
              await navigator.clipboard.writeText(shareInput.value);
            } else {
              shareInput.select();
              document.execCommand('copy');
            }
            if (toast) {
              toast.style.display = 'inline';
              setTimeout(() => { toast.style.display = 'none'; }, 2000);
            }
          } catch {
            shareInput.select();
          }
        });
      }
    })();
  </script>
</body>
</html>`;
}

export function renderNotFoundPage(message = 'Book not found') {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Not Found — Reading Tracker</title>
  <style>${STYLES}</style>
</head>
<body>
  <div class="container">
    <header>
      <h1><a href="/">Reading Tracker</a></h1>
    </header>
    <div class="card">
      <h2>404 — ${escapeHtml(message)}</h2>
      <p>We couldn't find the book you were looking for.</p>
      <p><a href="/" class="btn btn-primary">Back to Reading List</a></p>
    </div>
  </div>
</body>
</html>`;
}

