export function renderBookPage(book, baseUrl = '') {
  const id = escapeHtml(book.id);
  const title = escapeHtml(book.title);
  const author = escapeHtml(book.author);
  const notes = escapeHtml(book.notes);
  const isFinished = Boolean(book.finished || book.status === 'finished');
  const canonicalPath = `/books/${encodeURIComponent(book.id)}`;
  const shareUrl = baseUrl ? `${baseUrl}${canonicalPath}` : canonicalPath;

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>${title} — Reading Tracker</title>
  <style>${STYLES}</style>
</head>
<body>
  <div class="container">
    <header>
      <h1><a href="/">Reading Tracker</a></h1>
      <p><a href="/" class="btn btn-secondary btn-sm">&larr; Back to all books</a></p>
    </header>

    <article class="card" data-book-id="${id}">
      <div style="display: flex; justify-content: space-between; align-items: flex-start; gap: 1rem; flex-wrap: wrap;">
        <div>
          <h2 id="book-title" style="font-size: 1.65rem; margin-bottom: 0.25rem;">${title}</h2>
          <div id="book-author" class="book-author" style="font-size: 1.1rem;">by <span class="author-name">${author}</span></div>
        </div>
        <div>
          ${
            isFinished
              ? `<span class="badge badge-finished" id="book-status">Finished</span>`
              : `<span class="badge badge-reading" id="book-status">Currently Reading</span>`
          }
        </div>
      </div>

      <div class="detail-meta">
        ${
          !isFinished
            ? `<form method="POST" action="/books/${encodeURIComponent(book.id)}/finish" id="detail-finish-form" style="margin:0;">
                <button type="submit" class="btn btn-primary btn-sm">Mark as Finished</button>
              </form>`
            : `<form method="POST" action="/books/${encodeURIComponent(book.id)}/reading" id="detail-reading-form" style="margin:0;">
                <button type="submit" class="btn btn-secondary btn-sm">Move to Currently Reading</button>
              </form>`
        }
      </div>

      <section aria-labelledby="notes-heading">
        <h3 id="notes-heading" style="font-size: 1.05rem; margin-bottom: 0.5rem;">My Notes</h3>
        <div id="book-notes" class="notes-box">${notes ? notes : '<span style="color: var(--muted); font-style: italic;">No notes added yet.</span>'}</div>

        <details style="margin-bottom: 1rem;">
          <summary style="cursor: pointer; font-weight: 600; font-size: 0.9rem; color: var(--accent);">Edit Notes / Details</summary>
          <form method="POST" action="/books/${encodeURIComponent(book.id)}" id="edit-notes-form" style="margin-top: 0.75rem; display: flex; flex-direction: column; gap: 0.75rem;">
            <div class="form-group">
              <label for="edit-title">Title</label>
              <input type="text" id="edit-title" name="title" value="${title}" required />
            </div>
            <div class="form-group">
              <label for="edit-author">Author</label>
              <input type="text" id="edit-author" name="author" value="${author}" required />
            </div>
            <div class="form-group">
              <label for="edit-notes">Notes</label>
              <textarea id="edit-notes" name="notes">${notes}</textarea>
            </div>
            <div>
              <button type="submit" class="btn btn-primary btn-sm">Save Changes</button>
            </div>
          </form>
        </details>
      </section>

