import http from 'node:http';
import { URL } from 'node:url';
import querystring from 'node:querystring';
import { BookStore } from './store.js';
import { renderHomePage, renderBookPage, renderNotFoundPage } from './views.js';

function parseBody(req) {
  return new Promise((resolve, reject) => {
    let raw = '';
    req.on('data', (chunk) => {
      raw += chunk;
      if (raw.length > 1e6) {
        req.destroy();
        reject(new Error('Payload too large'));
      }
    });
    req.on('end', () => {
      if (!raw) {
        resolve({});
        return;
      }
      const contentType = (req.headers['content-type'] || '').toLowerCase();
      if (contentType.includes('application/json')) {
        try {
          resolve(JSON.parse(raw));
        } catch {
          reject(new Error('Invalid JSON'));
        }
      } else if (contentType.includes('application/x-www-form-urlencoded')) {
        resolve(querystring.parse(raw));
      } else {
        try {
          resolve(JSON.parse(raw));
        } catch {
          resolve(querystring.parse(raw));
        }
      }
    });
    req.on('error', reject);
  });
}

function wantsJson(req, pathname) {
  if (pathname.startsWith('/api/')) return true;
  const accept = (req.headers['accept'] || '').toLowerCase();
  if (accept.includes('application/json') && !accept.includes('text/html')) {
    return true;
  }
  return false;
}

function sendJson(res, status, data) {
  const payload = JSON.stringify(data, null, 2);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

function sendHtml(res, status, html) {
  res.writeHead(status, {
    'Content-Type': 'text/html; charset=utf-8',
    'Content-Length': Buffer.byteLength(html),
  });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

export function createApp({ dataFile } = {}) {
  const store = new BookStore(dataFile);

  const handler = async (req, res) => {
    try {
      const host = req.headers.host || 'localhost';
      const protocol = req.headers['x-forwarded-proto'] || 'http';
      const baseUrl = `${protocol}://${host}`;
      const parsedUrl = new URL(req.url || '/', baseUrl);
      const pathname = parsedUrl.pathname.replace(/\/+$/, '') || '/';
      const method = (req.method || 'GET').toUpperCase();

      // GET / -> Home page
      if (method === 'GET' && pathname === '/') {
        const books = store.getAll();
        if (wantsJson(req, pathname)) {
          return sendJson(res, 200, books);
        }
        return sendHtml(res, 200, renderHomePage(books));
      }

      // GET /api/books or GET /books
      if (method === 'GET' && (pathname === '/api/books' || pathname === '/books')) {
        const books = store.getAll();
        if (pathname === '/api/books' || wantsJson(req, pathname)) {
          return sendJson(res, 200, books);
        }
        return redirect(res, '/');
      }

      // POST /api/books or POST /books
      if (method === 'POST' && (pathname === '/api/books' || pathname === '/books')) {
        const body = await parseBody(req);
        try {
          const created = store.add({
            title: body.title,
            author: body.author,
            notes: body.notes,
            status: body.status,
            finished: body.finished,
          });
          if (wantsJson(req, pathname)) {
            return sendJson(res, 201, created);
          }
          return redirect(res, '/');
        } catch (err) {
          const status = err.status || 400;
          if (wantsJson(req, pathname)) {
            return sendJson(res, status, { error: err.message });
          }
          return sendHtml(res, status, renderNotFoundPage(err.message));
        }
      }

      // Match /api/books/:id/finish or /books/:id/finish or /book/:id/finish
      const finishMatch = pathname.match(/^\/(?:api\/)?books?\/([^/]+)\/finish$/);
      if (finishMatch && (method === 'POST' || method === 'PATCH' || method === 'PUT')) {
        const id = decodeURIComponent(finishMatch[1]);
        const updated = store.markFinished(id);
        if (!updated) {
          if (wantsJson(req, pathname)) {
            return sendJson(res, 404, { error: 'Book not found' });
          }
          return sendHtml(res, 404, renderNotFoundPage('Book not found'));
        }
        if (wantsJson(req, pathname)) {
          return sendJson(res, 200, updated);
        }
        const referer = req.headers.referer || '/';
        const redirectTarget = referer.includes(`/books/${encodeURIComponent(id)}`)
          ? `/books/${encodeURIComponent(id)}`
          : '/';
        return redirect(res, redirectTarget);
      }

      // Match /api/books/:id/reading or /books/:id/reading
      const readingMatch = pathname.match(/^\/(?:api\/)?books?\/([^/]+)\/reading$/);
      if (readingMatch && (method === 'POST' || method === 'PATCH' || method === 'PUT')) {
        const id = decodeURIComponent(readingMatch[1]);
        const updated = store.update(id, { status: 'reading', finished: false });
        if (!updated) {
          if (wantsJson(req, pathname)) {
            return sendJson(res, 404, { error: 'Book not found' });
          }
          return sendHtml(res, 404, renderNotFoundPage('Book not found'));
        }
        if (wantsJson(req, pathname)) {
          return sendJson(res, 200, updated);
        }
        return redirect(res, `/books/${encodeURIComponent(id)}`);
      }

      // Match /api/books/:id or /books/:id or /book/:id
      const itemMatch = pathname.match(/^\/(api\/)?books?\/([^/]+)$/);
      if (itemMatch) {
        const isApi = Boolean(itemMatch[1]);
        const id = decodeURIComponent(itemMatch[2]);

        if (method === 'GET') {
          const book = store.getById(id);
          if (!book) {
            if (isApi || wantsJson(req, pathname)) {
              return sendJson(res, 404, { error: 'Book not found' });
            }
            return sendHtml(res, 404, renderNotFoundPage('Book not found'));
          }
          if (isApi || wantsJson(req, pathname)) {
            return sendJson(res, 200, book);
          }
          return sendHtml(res, 200, renderBookPage(book, baseUrl));
        }

        if (method === 'PATCH' || method === 'PUT' || method === 'POST') {
          const body = await parseBody(req);
          try {
            const updated = store.update(id, body);
            if (!updated) {
              if (isApi || wantsJson(req, pathname)) {
                return sendJson(res, 404, { error: 'Book not found' });
              }
              return sendHtml(res, 404, renderNotFoundPage('Book not found'));
            }
            if (isApi || wantsJson(req, pathname)) {
              return sendJson(res, 200, updated);
            }
            return redirect(res, `/books/${encodeURIComponent(id)}`);
          } catch (err) {
            const status = err.status || 400;
            if (isApi || wantsJson(req, pathname)) {
              return sendJson(res, status, { error: err.message });
            }
            return sendHtml(res, status, renderNotFoundPage(err.message));
          }
        }

        if (method === 'DELETE') {
          const deleted = store.delete(id);
          if (!deleted) {
            return sendJson(res, 404, { error: 'Book not found' });
          }
          if (isApi || wantsJson(req, pathname)) {
            return sendJson(res, 200, { ok: true });
          }
          return redirect(res, '/');
        }
      }

      // 404 fallback
      if (wantsJson(req, pathname)) {
        return sendJson(res, 404, { error: 'Not found' });
      }
      return sendHtml(res, 404, renderNotFoundPage('Page not found'));
    } catch (err) {
      if (wantsJson(req, req.url || '')) {
        return sendJson(res, 400, { error: err.message || 'Bad request' });
      }
      return sendHtml(res, 500, renderNotFoundPage(err.message || 'Internal Server Error'));
    }
  };

  const server = http.createServer(handler);
  return { server, store, handler };
}

export function startServer({ port = process.env.PORT || 3000, host = '0.0.0.0', dataFile } = {}) {
  const { server, store } = createApp({ dataFile });
  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(Number(port), host, () => {
      const address = server.address();
      const actualPort = typeof address === 'object' && address ? address.port : port;
      console.log(`Reading tracker running at http://localhost:${actualPort}`);
      resolve({ server, store, port: actualPort });
    });
  });
}

// Run server if executed directly
const isMain =
  process.argv[1] &&
  (process.argv[1].endsWith('server.js') || process.argv[1].endsWith('index.js'));

if (isMain && process.env.NODE_ENV !== 'test') {
  startServer();
}

