import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { createApp } from '../src/server.js';
import { BookStore } from '../src/store.js';

describe('Reading Tracker App', () => {
  let tempDir;
  let dataFile;
  let server;
  let baseUrl;

  beforeEach(async () => {
    tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'reading-tracker-test-'));
    dataFile = path.join(tempDir, 'books.json');
    const app = createApp({ dataFile });
    server = app.server;
    await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
    const addr = server.address();
    baseUrl = `http://127.0.0.1:${addr.port}`;
  });

  afterEach(async () => {
    if (server) {
      await new Promise((resolve) => server.close(resolve));
    }
    if (tempDir && fs.existsSync(tempDir)) {
      fs.rmSync(tempDir, { recursive: true, force: true });
    }
  });

  it('renders home page with Currently Reading, Finished, and Add a Book form', async () => {
    const res = await fetch(`${baseUrl}/`);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain('Currently Reading');
    expect(html).toContain('Finished');
    expect(html).toContain('Add a Book');
    expect(html).toContain('<form id="add-book-form"');
  });

  it('adds a book via form submission, saves to JSON file, and persists across restarts', async () => {
    const formBody = new URLSearchParams({
      title: 'Dune',
      author: 'Frank Herbert',
      notes: 'Fear is the mind-killer.',
    }).toString();

    const postRes = await fetch(`${baseUrl}/books`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: formBody,
      redirect: 'manual',
    });
    expect(postRes.status).toBe(303);

    // Check JSON file directly
    const savedData = JSON.parse(fs.readFileSync(dataFile, 'utf8'));
    expect(savedData).toHaveLength(1);
    expect(savedData[0].title).toBe('Dune');
    expect(savedData[0].author).toBe('Frank Herbert');
    expect(savedData[0].notes).toBe('Fear is the mind-killer.');
    expect(savedData[0].status).toBe('reading');

    // Simulate server restart by creating a new store & server against the same JSON file
    const newStore = new BookStore(dataFile);
    const booksAfterRestart = newStore.getAll();
    expect(booksAfterRestart).toHaveLength(1);
    expect(booksAfterRestart[0].title).toBe('Dune');

    // Home page shows the book under Currently Reading
    const homeRes = await fetch(`${baseUrl}/`);
    const homeHtml = await homeRes.text();
    expect(homeHtml).toContain('Dune');
    expect(homeHtml).toContain('Frank Herbert');
    expect(homeHtml).toContain(`/books/${encodeURIComponent(savedData[0].id)}`);
  });

  it('marks a book as finished and moves it to the Finished section', async () => {
    // Add book via JSON API
    const createRes = await fetch(`${baseUrl}/api/books`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: 'Neuromancer',
        author: 'William Gibson',
        notes: 'The sky above the port was the color of television.',
      }),
    });
    expect(createRes.status).toBe(201);
    const created = await createRes.json();
    expect(created.status).toBe('reading');
    expect(created.finished).toBe(false);

    // Mark as finished via POST /books/:id/finish
    const finishRes = await fetch(`${baseUrl}/books/${encodeURIComponent(created.id)}/finish`, {
      method: 'POST',
      redirect: 'manual',
    });
    expect(finishRes.status).toBe(303);

    // Verify JSON file updated
    const savedData = JSON.parse(fs.readFileSync(dataFile, 'utf8'));
    expect(savedData[0].status).toBe('finished');
    expect(savedData[0].finished).toBe(true);

    // Verify home page shows it in finished
    const homeRes = await fetch(`${baseUrl}/`);
    const homeHtml = await homeRes.text();
    expect(homeHtml).toContain('data-status="finished"');
    expect(homeHtml).toContain('Neuromancer');
  });

  it('renders a dedicated shareable page for a single book with title, author, and notes', async () => {
    const createRes = await fetch(`${baseUrl}/api/books`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: 'Project Hail Mary',
        author: 'Andy Weir',
        notes: 'Amaze! Great sci-fi adventure.',
      }),
    });
    const book = await createRes.json();

    // Visit the single book URL directly (like someone clicking a shared link)
    const detailRes = await fetch(`${baseUrl}/books/${encodeURIComponent(book.id)}`);
    expect(detailRes.status).toBe(200);
    const detailHtml = await detailRes.text();

    expect(detailHtml).toContain('Project Hail Mary');
    expect(detailHtml).toContain('Andy Weir');
    expect(detailHtml).toContain('Amaze! Great sci-fi adventure.');
    expect(detailHtml).toContain(`/books/${encodeURIComponent(book.id)}`);
  });

  it('allows updating notes on a book and returns 404 for unknown books', async () => {
    const createRes = await fetch(`${baseUrl}/api/books`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: 'Piranesi',
        author: 'Susanna Clarke',
        notes: 'Initial note',
      }),
    });
    const book = await createRes.json();

    const patchRes = await fetch(`${baseUrl}/api/books/${encodeURIComponent(book.id)}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ notes: 'The House is infinite.' }),
    });
    expect(patchRes.status).toBe(200);
    const updated = await patchRes.json();
    expect(updated.notes).toBe('The House is infinite.');

    const missingRes = await fetch(`${baseUrl}/books/non-existent-id`);
    expect(missingRes.status).toBe(404);
  });
});

